 * Cell address parsing and ordering: one or two letters for the column
 * (A..Z, AA..ZZ) followed by one to three digits for the row (>= 1).
 */

const ADDRESS_RE = /^([A-Z]{1,2})([0-9]{1,3})$/

/** Converts an uppercase column-letter string (A..ZZ) to a 1-based index. */
export function lettersToIndex(letters) {
  let index = 0
  for (const ch of letters) {
    index = index * 26 + (ch.charCodeAt(0) - 64)
  }
  return index
}

/** Converts a 1-based column index back to its letter string. */
export function indexToLetters(index) {
  let n = index
  let out = ''
  while (n > 0) {
    n -= 1
    out = String.fromCharCode(65 + (n % 26)) + out
    n = Math.floor(n / 26)
  }
  return out
}

/**
 * Parses an already-uppercased address string. Returns `{ valid, col, row }`;
 * `col`/`row` are only meaningful when `valid` is true.
 */
export function parseAddress(text) {
  const m = ADDRESS_RE.exec(text)
  if (!m) return { valid: false }
  const row = Number(m[2])
  if (row < 1) return { valid: false }
  return { valid: true, col: lettersToIndex(m[1]), row }
}

/** Builds the canonical address string for a column index and row number. */
export function addressFor(col, row) {
  return `${indexToLetters(col)}${row}`
}

/** Orders addresses by ascending column, then ascending row. */
export function compareAddresses(a, b) {
  const pa = parseAddress(a)
  const pb = parseAddress(b)
  if (pa.col !== pb.col) return pa.col - pb.col
  return pa.row - pb.row
}
"}

