{"file_path":"/home/user/deepseek-harness/.proving-ground/runs/h3-baseline-sonnet-t5-20260925T221232Z/cell-aGFjF0/src/lexer.js","content":"/**
 * Tokenizer for formula bodies (the text following a leading `=`).
 */

export class FormulaSyntaxError extends Error {}

const TWO_CHAR_OPS = {
  '<=': 'LE',
  '>=': 'GE',
  '<>': 'NE',
}

const ONE_CHAR_OPS = {
  '(': 'LPAREN',
  ')': 'RPAREN',
  ',': 'COMMA',
  ':': 'COLON',
  '^': 'CARET',
  '*': 'STAR',
  '/': 'SLASH',
  '+': 'PLUS',
  '-': 'MINUS',
  '=': 'EQ',
  '<': 'LT',
  '>': 'GT',
}

/** Tokenizes a formula body. Throws `FormulaSyntaxError` on an unknown character. */
export function tokenize(text) {
  const tokens = []
  let i = 0
  const n = text.length
  while (i < n) {
    const c = text[i]
    if (c === ' ' || c === '\t') {
      i += 1
      continue
    }
    if (c >= '0' && c <= '9') {
      let j = i + 1
      while (j < n && text[j] >= '0' && text[j] <= '9') j += 1
      if (text[j] === '.' && text[j + 1] >= '0' && text[j + 1] <= '9') {
        j += 1
        while (j < n && text[j] >= '0' && text[j] <= '9') j += 1
      }
      tokens.push({ type: 'NUMBER', text: text.slice(i, j) })
      i = j
      continue
    }
    if (/[A-Za-z]/.test(c)) {
      let j = i + 1
      while (j < n && /[A-Za-z]/.test(text[j])) j += 1
      while (j < n && text[j] >= '0' && text[j] <= '9') j += 1
      tokens.push({ type: 'IDENT', text: text.slice(i, j) })
      i = j
      continue
    }
    const two = text.slice(i, i + 2)
    if (TWO_CHAR_OPS[two]) {
      tokens.push({ type: TWO_CHAR_OPS[two], text: two })
      i += 2
      continue
    }
    if (ONE_CHAR_OPS[c]) {
      tokens.push({ type: ONE_CHAR_OPS[c], text: c })
      i += 1
      continue
    }
    throw new FormulaSyntaxError(`unexpected character ${c}`)
  }
  return tokens
}
"}

