{"file_path":"/home/user/deepseek-harness/.proving-ground/runs/h3-baseline-sonnet-t5-20260925T221232Z/cell-aGFjF0/src/parser.js","content":"/**
 * Recursive-descent parser for formula bodies. Produces an AST or throws
 * `FormulaSyntaxError` when the token stream does not match the grammar.
 *
 * Precedence, loosest to tightest: comparisons, `+`/`-`, `*`/`/`, `^`
 * (right-associative), then a leading unary `+`/`-` (tighter than `^`).
 * A range (`A1:B3`) is only accepted directly as a function argument.
 */
import { tokenize, FormulaSyntaxError } from './lexer.js'

const COMPARISON_TYPES = new Set(['EQ', 'NE', 'LT', 'LE', 'GT', 'GE'])
const FUNCTION_NAMES = new Set(['SUM', 'MIN', 'MAX', 'COUNT', 'AVG', 'ABS', 'IF'])

class Parser {
  constructor(tokens) {
    this.tokens = tokens
    this.pos = 0
  }

  peek(offset = 0) {
    return this.tokens[this.pos + offset]
  }

  expect(type) {
    const t = this.peek()
    if (!t || t.type !== type) throw new FormulaSyntaxError(`expected ${type}`)
    this.pos += 1
    return t
  }

  parseComparison() {
    let node = this.parseAdditive()
    while (this.peek() && COMPARISON_TYPES.has(this.peek().type)) {
      const op = this.peek().type
      this.pos += 1
      const right = this.parseAdditive()
      node = { type: 'Binary', op, left: node, right }
    }
    return node
  }

  parseAdditive() {
    let node = this.parseMultiplicative()
    while (this.peek() && (this.peek().type === 'PLUS' || this.peek().type === 'MINUS')) {
      const op = this.peek().type
      this.pos += 1
      const right = this.parseMultiplicative()
      node = { type: 'Binary', op, left: node, right }
    }
    return node
  }

  parseMultiplicative() {
    let node = this.parsePower()
    while (this.peek() && (this.peek().type === 'STAR' || this.peek().type === 'SLASH')) {
      const op = this.peek().type
      this.pos += 1
      const right = this.parsePower()
      node = { type: 'Binary', op, left: node, right }
    }
    return node
  }

