 * The value model shared by evaluation and formatting: a number, text, a
 * boolean, or one of the six error tokens.
 */

export const ERROR_TOKENS = ['#DIV/0!', '#REF!', '#VALUE!', '#CYCLE!', '#NAME?', '#ERR!']

export function numVal(value) {
  return { type: 'number', value }
}
export function textVal(value) {
  return { type: 'text', value }
}
export function boolVal(value) {
  return { type: 'bool', value }
}
export function errVal(token) {
  return { type: 'error', token }
}

/** Reads a value as a number for an arithmetic position: bool -> 1/0, text -> #VALUE!. */
export function toNumber(v) {
  if (v.type === 'error') return v
  if (v.type === 'number') return v
  if (v.type === 'bool') return numVal(v.value ? 1 : 0)
  return errVal('#VALUE!')
}

/** Applies a binary arithmetic operator, honoring the left-operand-wins error rule. */
export function arithmetic(op, leftVal, rightVal) {
  const l = toNumber(leftVal)
  if (l.type === 'error') return l
  const r = toNumber(rightVal)
  if (r.type === 'error') return r
  let result
  switch (op) {
    case 'PLUS':
      result = l.value + r.value
      break
    case 'MINUS':
      result = l.value - r.value
      break
    case 'STAR':
      result = l.value * r.value
      break
    case 'SLASH':
      if (r.value === 0) return errVal('#DIV/0!')
      result = l.value / r.value
      break
    case 'CARET':
      result = Math.pow(l.value, r.value)
      break
    default:
      throw new Error(`unknown arithmetic operator ${op}`)
  }
  if (!Number.isFinite(result)) return errVal('#DIV/0!')
  return numVal(result)
}

export function unaryArithmetic(op, val) {
  const n = toNumber(val)
  if (n.type === 'error') return n
  const result = op === 'MINUS' ? -n.value : n.value
  if (!Number.isFinite(result)) return errVal('#DIV/0!')
  return numVal(result)
}

function rank(v) {
  if (v.type === 'number') return 0
  if (v.type === 'text') return 1
  return 2 // bool
}

/** -1, 0, or 1: numbers by value, text by code point, booleans false < true; across kinds number < text < bool. */
function compareValues(a, b) {
  const ra = rank(a)
  const rb = rank(b)
  if (ra !== rb) return ra < rb ? -1 : 1
  if (a.type === 'number') return a.value < b.value ? -1 : a.value > b.value ? 1 : 0
  if (a.type === 'text') return a.value < b.value ? -1 : a.value > b.value ? 1 : 0
  // bool: false < true
  const na = a.value ? 1 : 0
  const nb = b.value ? 1 : 0
  return na - nb
}

/** Applies a comparison operator, honoring the left-operand-wins error rule. */
export function compare(op, leftVal, rightVal) {
  if (leftVal.type === 'error') return leftVal
  if (rightVal.type === 'error') return rightVal
  const c = compareValues(leftVal, rightVal)
  switch (op) {
    case 'EQ':
      return boolVal(c === 0)
    case 'NE':
      return boolVal(c !== 0)
    case 'LT':
      return boolVal(c < 0)
    case 'LE':
      return boolVal(c <= 0)
    case 'GT':
      return boolVal(c > 0)
    case 'GE':
      return boolVal(c >= 0)
    default:
      throw new Error(`unknown comparison operator ${op}`)
  }
}

/** Rounds a finite number to ten significant digits and prints it as JavaScript would. */
export function formatNumber(n) {
  if (n === 0) return '0'
  const rounded = Number(n.toPrecision(10))
  return String(rounded)
}

export function formatValue(v) {
  switch (v.type) {
    case 'number':
      return formatNumber(v.value)
    case 'error':
      return v.token
    case 'bool':
      return v.value ? 'TRUE' : 'FALSE'
    case 'text':
      return v.value
    default:
      throw new Error(`unknown value type ${v.type}`)
  }
}
