 * Parses the sheet text format into an ordered map of declared cells.
 */
import { parseAddress } from './address.js'
import { numVal, textVal, errVal, ERROR_TOKENS } from './values.js'
import { parseFormula } from './parser.js'
import { FormulaSyntaxError } from './lexer.js'

export class SheetError extends Error {
  constructor(line, message) {
    super(message)
    this.line = line
  }
}

const LITERAL_NUMBER_RE = /^-?[0-9]+(\.[0-9]+)?$/
const ERROR_TOKEN_SET = new Set(ERROR_TOKENS)

function parseLiteral(content) {
  if (content === '') return numVal(0)
  if (LITERAL_NUMBER_RE.test(content)) return numVal(Number(content))
  if (ERROR_TOKEN_SET.has(content)) return errVal(content)
  return textVal(content)
}

/**
 * Parses the sheet text. Returns a Map from address to a cell record:
 * `{ kind: 'literal', value }` or `{ kind: 'formula', ast, parseError }`.
 * Throws `SheetError` for an invalid address or a duplicate declaration.
 */
export function parseSheet(input) {
  const rawLines = input.split('\n')
  if (rawLines.length > 0 && rawLines[rawLines.length - 1] === '') rawLines.pop()

  const cells = new Map()

  for (let i = 0; i < rawLines.length; i += 1) {
    const lineNo = i + 1
    const raw = rawLines[i]
    const stripped = raw.replace(/^[ \t]+/, '')
    if (stripped === '' || stripped.startsWith('#')) continue

    let idx = 0
    while (idx < stripped.length && stripped[idx] !== ' ' && stripped[idx] !== '\t') idx += 1
    const addrText = stripped.slice(0, idx).toUpperCase()
    const rest = stripped.slice(idx)
    const content = rest.replace(/^[ \t]+/, '')

    const parsed = parseAddress(addrText)
    if (!parsed.valid) {
      throw new SheetError(lineNo, `invalid cell address ${addrText}`)
    }
    if (cells.has(addrText)) {
      throw new SheetError(lineNo, `cell ${addrText} is declared twice`)
    }

    if (content.startsWith('=')) {
      try {
        const ast = parseFormula(content.slice(1))
        cells.set(addrText, { kind: 'formula', ast, parseError: false })
      } catch (err) {
        if (err instanceof FormulaSyntaxError) {
          cells.set(addrText, { kind: 'formula', ast: null, parseError: true })
        } else {
          throw err
        }
      }
    } else {
      cells.set(addrText, { kind: 'literal', value: parseLiteral(content) })
    }
  }

  return cells
}
"}

