  const state = new Map() // address -> 'in-progress' | 'done'

  function evalCell(addr) {
    if (memo.has(addr)) return memo.get(addr)
    const cell = cells.get(addr)
    if (!cell) {
      const v = numVal(0)
      memo.set(addr, v)
      return v
    }
    if (cell.kind === 'literal') {
      memo.set(addr, cell.value)
      return cell.value
    }
    if (state.get(addr) === 'in-progress') {
      return errVal('#CYCLE!')
    }
    if (cell.parseError) {
      const v = errVal('#ERR!')
      memo.set(addr, v)
      return v
