  const args = process.argv.slice(2)
  if (args.length !== 1 || (args[0] !== 'values' && args[0] !== 'deps')) {
    fail('usage: cli.js values|deps')
    return
  }
  const mode = args[0]

  const input = readFileSync(0, 'utf8')

  let cells
  try {
    cells = parseSheet(input)
  } catch (err) {
    if (err instanceof SheetError) {
      fail(`line ${err.line}: ${err.message}`)
      return
    }
    throw err
  }

  const addresses = [...cells.keys()].sort((a, b) => {
    const pa = parseAddress(a)
    const pb = parseAddress(b)
    if (pa.col !== pb.col) return pa.col - pb.col
    return pa.row - pb.row
  })

  const lines = []
  if (mode === 'values') {
    const evaluator = createEvaluator(cells)
    for (const addr of addresses) {
      lines.push(`${addr}=${formatValue(evaluator.evalCell(addr))}`)
    }
  } else {
    for (const addr of addresses) {
      const cell = cells.get(addr)
      const deps = cell.kind === 'formula' && !cell.parseError ? collectDeps(cell.ast) : []
      lines.push(`${addr}:${deps.map((d) => ` ${d}`).join('')}`)
    }
  }

  process.stdout.write(lines.length ? `${lines.join('\n')}\n` : '')
  process.exit(0)
}

main()
"}

